<?php
namespace App\Http\Controllers;
use App\Models\Order;use App\Models\ReturnItem;use App\Models\ReturnModel;use App\Models\StockMovement;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ReturnController extends Controller {private function manager(Request $r):void{abort_unless($r->user()?->isManager(),403);}public function index(Request $r){$this->manager($r);$returns=ReturnModel::with(['order','customer'])->latest()->paginate(15);return view('returns.index',compact('returns'));}public function create(Request $r){$this->manager($r);$orders=Order::with('customer')->whereIn('status',['confirmed','completed'])->latest()->get();return view('returns.create',compact('orders'));}public function store(Request $r){$this->manager($r);$data=$r->validate(['order_id'=>'required|exists:orders,id','reason'=>'required|string|max:1000','items'=>'required|array|min:1','items.*.order_item_id'=>'required|distinct|exists:order_items,id','items.*.quantity'=>'required|integer|min:1']);$return=DB::transaction(function()use($data,$r){$order=Order::lockForUpdate()->with('items')->findOrFail($data['order_id']);$ret=ReturnModel::create(['return_number'=>'RET-'.now()->format('YmdHis').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6)),'order_id'=>$order->id,'customer_id'=>$order->customer_id,'processed_by'=>$r->user()->id,'status'=>'approved','refund_status'=>'pending','reason'=>$data['reason']]);$refund=0;foreach($data['items'] as $row){$item=$order->items->firstWhere('id',$row['order_item_id']);abort_unless($item,422,'Order item does not belong to this order.');$already=ReturnItem::where('order_item_id',$item->id)->sum('quantity');$remaining=$item->quantity-$already;abort_if($row['quantity']>$remaining,422,'Return quantity exceeds remaining sold quantity.');$line=$row['quantity']*(float)$item->unit_price;$refund+=$line;$product=$item->product()->lockForUpdate()->first();$before=$product->stock_quantity;$product->increment('stock_quantity',$row['quantity']);$after=$product->fresh()->stock_quantity;ReturnItem::create(['return_id'=>$ret->id,'order_item_id'=>$item->id,'product_id'=>$product->id,'quantity'=>$row['quantity'],'unit_price'=>$item->unit_price,'line_total'=>$line]);StockMovement::create(['product_id'=>$product->id,'user_id'=>$r->user()->id,'type'=>'RETURN','quantity'=>$row['quantity'],'balance_before'=>$before,'balance_after'=>$after,'reason'=>'Return '.$ret->return_number]);}$ret->update(['refund_amount'=>$refund]);return $ret;});return redirect()->route('returns.index')->with('success','Return processed and stock restored.');}}
